    """Tokenize HTML and record absolute (start, end) char ranges to delete."""

    def __init__(self, text):
        super().__init__(convert_charrefs=False)
        self.deletes = []
        self._in_script = False
        self._script_start = None
        self._script_open_depth = 0
        # absolute offset of the first char of each line (1-based line no.)
        offs = [0]
        for ln in text.splitlines(keepends=True):
            offs.append(offs[-1] + len(ln))
        self._offs = offs

    def _abs(self, pos):
        line, col = pos
        i = max(0, min(line - 1, len(self._offs) - 1))
        return self._offs[i] + col

    def _del(self, start, end):
        if start is not None and end is not None and end > start:
            self.deletes.append((start, end))

    # ------------------------------------------------------------- tags ---

    def handle_starttag(self, tag, attrs):
        raw = self.get_starttag_text()
        start = self._abs(self.getpos())

        if tag == "script":
            self._in_script = True
            if self._script_start is None:
                self._script_start = start
